use std :: sync :: Arc ; use forge_domain :: { Agent , ContextMessage , Conversation , Role , TextMessage } ; use forge_template :: Element ; use crate :: utils :: format_display_path ; use crate :: { EnvironmentInfra , FsReadService } ; use crate :: file_tracking :: FileChangeDetector ; use std :: collections :: HashMap ; use std :: path :: PathBuf ; use forge_domain :: { Agent , AgentId , Context , Conversation , ConversationId , Environment , FileOperation , Metrics , ModelId , ProviderId , ToolKind , } ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: services :: Content ; use crate :: { FsReadService , ReadOutput , compute_hash } ; use fake :: { Fake , Faker } ; impl < S : FsReadService + EnvironmentInfra < Config = forge_config :: ForgeConfig > > ChangedFiles < S > { # [doc = " Detects externally changed files and renders a notification if changes"] # [doc = " are found. Updates file hashes in conversation metrics to prevent"] # [doc = " duplicate notifications."] pub async fn update_file_stats (& self , mut conversation : Conversation) -> Conversation { use crate :: file_tracking :: FileChangeDetector ; let parallel_file_reads = self . services . get_config () . map (| c | c . max_parallel_file_reads) . unwrap_or (4) ; let changes = FileChangeDetector :: new (self . services . clone ()) . detect (& conversation . metrics , parallel_file_reads) . await ; if changes . is_empty () { return conversation ; } let mut updated_metrics = conversation . metrics . clone () ; for change in & changes { if let Some (path_str) = change . path . to_str () && let Some (metrics) = updated_metrics . file_operations . get_mut (path_str) { metrics . content_hash = change . content_hash . clone () ; } } conversation . metrics = updated_metrics ; let cwd = self . services . get_environment () . cwd ; let file_elements : Vec < Element > = changes . iter () . map (| change | { let display_path = format_display_path (& change . path , & cwd) ; Element :: new ("file") . text (display_path) }) . collect () ; let notification = Element :: new ("information") . append (Element :: new ("critical") . text ("The following files have been modified externally. Please re-read them if its relevant for the task.") ,) . append (Element :: new ("files") . append (file_elements)) . to_string () ; let context = conversation . context . take () . unwrap_or_default () ; let message = TextMessage :: new (Role :: User , notification) . droppable (true) . model (self . agent . model . clone ()) ; conversation = conversation . context (context . add_message (ContextMessage :: from (message))) ; conversation } }